CREATE TABLE IF NOT EXISTS "Role" (id BIGSERIAL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, description TEXT NOT NULL, permissions JSON NOT NULL, CONSTRAINT chk_Role_unsigned_integer_id CHECK (id BETWEEN 0 AND 4294967295));
CREATE SEQUENCE IF NOT EXISTS Role_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;